def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    for index, operation in enumerate(ops):
        tokens = operation.split()
        if not tokens:
            rejected.append(index)
            continue

        verb = tokens[0]
        action = None

        if verb == "open" and len(tokens) == 3:
            account, amount_text = tokens[1], tokens[2]
            if amount_text.isdigit() and all("0" <= c <= "9" for c in amount_text):
                amount = int(amount_text)
                if account not in balances:
                    balances[account] = amount
                    action = ("open", account, amount)

        elif verb == "deposit" and len(tokens) == 3:
            account, amount_text = tokens[1], tokens[2]
            if account in balances and amount_text.isdigit() and all("0" <= c <= "9" for c in amount_text):
                amount = int(amount_text)
                if amount > 0:
                    balances[account] += amount
                    action = ("balance", account, -amount)

        elif verb == "withdraw" and len(tokens) == 3:
            account, amount_text = tokens[1], tokens[2]
            if account in balances and account not in frozen and amount_text.isdigit() and all("0" <= c <= "9" for c in amount_text):
                amount = int(amount_text)
                if amount > 0 and balances[account] >= amount:
                    balances[account] -= amount
                    action = ("balance", account, amount)

        elif verb == "transfer" and len(tokens) == 4:
            source, target, amount_text = tokens[1], tokens[2], tokens[3]
            if (
                source != target
                and source in balances
                and target in balances
                and source not in frozen
                and amount_text.isdigit()
                and all("0" <= c <= "9" for c in amount_text)
            ):
                amount = int(amount_text)
                if amount > 0 and balances[source] >= amount:
                    balances[source] -= amount
                    balances[target] += amount
                    action = ("transfer", source, target, amount)

        elif verb == "freeze" and len(tokens) == 2:
            account = tokens[1]
            if account in balances and account not in frozen:
                frozen.add(account)
                action = ("freeze", account, False)

        elif verb == "unfreeze" and len(tokens) == 2:
            account = tokens[1]
            if account in balances and account in frozen:
                frozen.remove(account)
                action = ("freeze", account, True)

        elif verb == "undo" and len(tokens) == 1:
            if not history:
                rejected.append(index)
                continue

            action = history.pop()
            kind = action[0]

            if kind == "open":
                _, account, _ = action
                del balances[account]
                frozen.discard(account)
            elif kind == "balance":
                _, account, delta = action
                balances[account] += delta
            elif kind == "transfer":
                _, source, target, amount = action
                balances[source] += amount
                balances[target] -= amount
            elif kind == "freeze":
                _, account, was_frozen = action
                if was_frozen:
                    frozen.add(account)
                else:
                    frozen.discard(account)
            continue

        if action is None:
            rejected.append(index)
        else:
            history.append(action)

    return balances, rejected
